namespace ghidra.framework.main;







using docking;
using docking.tool;
using docking.widgets.table;
using ghidra.framework.model;
using ghidra.framework.project.tool;
using ghidra.util;

public class PickToolDialog : DialogComponentProvider {

	private FrontEndTool tool;
	private ToolTableModel model;
	private GTable table;
	private ToolTemplate selectedTemplate;
	private Class<DomainObject> domainClass;

	protected PickToolDialog(FrontEndTool tool, Class<DomainObject> domainClass) : base("Pick Tool", true)
    {
		this.tool = tool;
		this.domainClass = domainClass;

		setHelpLocation(new HelpLocation(ToolConstants.TOOL_HELP_TOPIC, "Set Tool Associations"));

		addWorkPanel(createWorkPanel());

		addOKButton();
		addCancelButton();

		setPreferredSize(300, 400);
		setRememberLocation(false);
	}

	private JComponent createWorkPanel() {
		JPanel mainPanel = new JPanel(new BorderLayout());

		model = new ToolTableModel();
		table = new GTable(model);

		table.setPreferredRowHeight(28); // make big enough for tool icons
		table.setColumnHeaderPopupEnabled(false); // don't allow column configuration
		table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		table.setDefaultRenderer(typeof(GhidraToolTemplate), new ToolTemplateRenderer());

		table.getSelectionModel().addListSelectionListener(e => {
			if (e.getValueIsAdjusting()) {
				return;
			}

			int selectedRow = table.getSelectedRow();
			ToolTemplate template = model.getRowObject(selectedRow);
			okButton.setEnabled(template != null);
		});

		loadList();

		mainPanel.add(new JScrollPane(table), BorderLayout.CENTER);

		return mainPanel;
	}

	private void loadList() {
		Project project = tool.getProject();
		ToolServices toolServices = project.getToolServices();
		Set<ToolTemplate> compatibleTools = toolServices.getCompatibleTools(domainClass);
		model.setData(new(compatibleTools));
	}

	void showDialog() {
		clearStatusText();
		tool.showDialog(this);
	}

	/* @Override */
	protected void okCallback() {
		int selectedRow = table.getSelectedRow();
		selectedTemplate = model.getRowObject(selectedRow);
		close();
	}

	ToolTemplate getSelectedToolTemplate() {
		return selectedTemplate;
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private class ToolTableModel : AbstractSortedTableModel<ToolTemplate> {

		private List<ToolTemplate> data;

		ToolTableModel() : base(0)
    {
			this.data = Collections.emptyList();
		}

		void setData(List<ToolTemplate> data) {
			this.data = data;
			fireTableDataChanged();
		}

		/* @Override */
		public string getName() {
			return "Tool Picker";
		}

		/* @Override */
		public object getColumnValueForRow(ToolTemplate t, int column) {
			return t;
		}

		/* @Override */
		public string getColumnName(int column) {
			return "Tool";
		}

		/* @Override */
		public Class<object> getColumnClass(int column) {
			return typeof(GhidraToolTemplate);
		}

		/* @Override */
		public List<ToolTemplate> getModelData() {
			return data;
		}

		/* @Override */
		public bool isSortable(int columnIndex) {
			return columnIndex == 0;
		}

		/* @Override */
		public int getColumnCount() {
			return 1;
		}

		/* @Override */
		public int getRowCount() {
			return data.size();
		}

		/* @Override */
		protected Comparator<ToolTemplate> createSortComparator(int column) {
			return new ToolTemplateComparator();
		}
	}

	private class ToolTemplateComparator : Comparator<ToolTemplate> {
		/* @Override */
		public int compare(ToolTemplate o1, ToolTemplate o2) {
			return o1.getName().compareTo(o2.getName());
		}
	}

	private class ToolTemplateRenderer : GTableCellRenderer {
		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {

			JLabel renderer = (JLabel) base.getTableCellRendererComponent(data);

			object value = data.getValue();

			ToolTemplate template = (ToolTemplate) value;
			if (template == null) {
				return renderer;
			}

			renderer.setIcon(template.getIcon());
			renderer.setText(template.getName());

			return renderer;
		}
	}
}
